<?php
namespace App\Filament\Resources\AdmissionBills;
use App\Models\AdmissionBill; use App\Filament\Resources\AdmissionBills\Pages; use Filament\Forms\Components\{DatePicker,Select,TextInput}; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\{Actions\DeleteAction,Actions\EditAction,Columns\TextColumn,Table}; use BackedEnum; use UnitEnum;
class AdmissionBillResource extends Resource { protected static ?string $slug='admission-bills'; protected static ?string $model=AdmissionBill::class; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedDocumentCurrencyDollar; protected static string|UnitEnum|null $navigationGroup='Penerimaan Mahasiswa Baru'; protected static ?string $navigationLabel='Tagihan PMB'; protected static ?string $modelLabel='Tagihan PMB'; protected static ?string $pluralModelLabel='Tagihan PMB'; public static function form(Schema $schema):Schema{return $schema->components([Select::make('applicant_id')->label('Pendaftar')->relationship('applicant','registration_number')->searchable()->preload()->required(),Select::make('fee_type_id')->label('Jenis Biaya')->relationship('feeType','name')->searchable()->preload(),TextInput::make('bill_number')->label('Nomor Tagihan')->required()->maxLength(80),TextInput::make('purpose')->label('Keperluan')->required()->maxLength(40),DatePicker::make('issued_at')->label('Diterbitkan Pada')->required(),DatePicker::make('due_date')->label('Jatuh Tempo')->required(),TextInput::make('amount')->label('Nominal')->numeric()->minValue(0)->required(),TextInput::make('paid_amount')->label('Terbayar')->numeric()->minValue(0)->default(0),Select::make('status')->label('Status')->options(['unpaid'=>'Belum Bayar','partial'=>'Sebagian','paid'=>'Lunas','overdue'=>'Jatuh Tempo'])->default('unpaid')->required()]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('bill_number')->label('Nomor'),TextColumn::make('applicant.registration_number')->label('Pendaftar'),TextColumn::make('amount')->label('Nominal')->money('IDR'),TextColumn::make('paid_amount')->label('Terbayar')->money('IDR'),TextColumn::make('status')->label('Status')->badge(),TextColumn::make('due_date')->label('Jatuh Tempo')->date()])->actions([EditAction::make()->label('Ubah')->visible(fn(AdmissionBill $r)=>$r->status!=='paid'),DeleteAction::make()->label('Hapus')->visible(fn(AdmissionBill $r)=>$r->paid_amount==0)->requiresConfirmation()]);} public static function getPages():array{return ['index'=>Pages\ListAdmissionBills::route('/'),'create'=>Pages\CreateAdmissionBill::route('/create'),'edit'=>Pages\EditAdmissionBill::route('/{record}/edit')];}}
